<script setup lang="ts">import{onMounted,ref}from 'vue';import{useRouter}from 'vue-router';import{seriesStore,loadSeries}from '../stores/series';import{runStore,loadRuns}from '../stores/runs';import{createRun}from '../api/runs';import{canEdit}from '../stores/auth';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import RunTable from '../components/RunTable.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const router=useRouter();const{error,busy,execute}=useTask();const form=ref({name:'下周日配 · 杭州玫瑰',series_id:1,horizon:14,season:7});const refresh=()=>execute(async()=>{await Promise.all([loadSeries(),loadRuns()])});const submit=()=>execute(async()=>{const r=await createRun(form.value);await router.push('/results/'+r.id)});onMounted(refresh);</script><template><PageHeading index="03 / BACKTEST" title="先回测，再预测" subtitle="留出最近 28 天逐日回测，模型每一步只看到此前观测。"/><ErrorNotice :message="error" @retry="refresh"/><div class="workbench"><form v-if="canEdit" @submit.prevent="submit"><h2>建立预测任务</h2><label>档案名称<input v-model="form.name" required minlength="2" maxlength="100"/></label><label>日配序列<select v-model.number="form.series_id"><option v-for="s in seriesStore.items" :value="s.id" :key="s.id">{{s.name}} / {{s.observation_count}}天</option></select></label><div class="form-grid"><label>预测天数<input v-model.number="form.horizon" type="number" min="1" max="30" required/></label><label>季节周期 / 天<input v-model.number="form.season" type="number" min="2" max="30" required/></label></div><button class="primary" :disabled="busy">{{busy?'正在提交…':'提交后台回测 →'}}</button></form><aside><p class="eyebrow">METHOD NOTE / 03</p><h2>一次比较，四个候选。</h2><p>季节朴素法与 α 为 0.2 / 0.5 / 0.8 的指数平滑；以滚动回测 MAE 最小者作为本次模型。</p><p>WAPE = 绝对误差合计 ÷ 实际需求合计。经验区间来自残差分位，节假日和突发需求仍需人工判断。</p><small>观测下限：42 天且至少三个季节周期。</small></aside></div><div class="section-heading"><h2>预测任务记录</h2><button @click="refresh">刷新状态 ↻</button></div><RunTable :items="runStore.items"/></template>
